style.css:
/* Színes háttér és animált szikrák */
body {
    background: radial-gradient(circle, #ff0000, #ff7300, #fffb00, #00ff0a, #00aaff, #5a00ff, #ff00fa);
    background-size: 400% 400%;
    animation: gradientBackground 6s ease infinite;
    color: #fff;
}

/* Animált szikrák */
@keyframes gradientBackground {
    0% {
        background-position: 0% 50%;
    }
    50% {
        background-position: 100% 50%;
    }
    100% {
        background-position: 0% 50%;
    }
}

/* Szövegek dinamikus megjelenése */
h1, h2, h3, p {
    text-shadow: 0 0 10px #ff0000, 0 0 20px #ff7300, 0 0 30px #fffb00, 0 0 40px #00ff0a, 0 0 50px #00aaff, 0 0 60px #5a00ff, 0 0 70px #ff00fa;
    animation: textGlow 1.5s ease infinite alternate;
}

/* Szöveg fénycsillogás */
@keyframes textGlow {
    0% {
        text-shadow: 0 0 10px #ff0000, 0 0 20px #ff7300, 0 0 30px #fffb00, 0 0 40px #00ff0a, 0 0 50px #00aaff, 0 0 60px #5a00ff, 0 0 70px #ff00fa;
    }
    100% {
        text-shadow: 0 0 20px #ff0000, 0 0 30px #ff7300, 0 0 40px #fffb00, 0 0 50px #00ff0a, 0 0 60px #00aaff, 0 0 70px #5a00ff, 0 0 80px #ff00fa;
    }
}
